<?php function page_start(string $title): void { $u = user(); ?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#090d1a"><meta name="robots" content="noindex"><title><?=h($title)?> | گیم‌زون</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/rastikerdar/vazirmatn@v33.003/Vazirmatn-font-face.css"><link rel="stylesheet" href="assets/css/style.css?v=<?=filemtime(__DIR__.'/assets/css/style.css')?>"><style>body{font-family:Vazirmatn,Tahoma,sans-serif}button,input,select,textarea{font-family:inherit}</style></head><body><header class="header"><div class="container nav"><a class="brand" href="index.php"><span class="brand-icon">✣</span><span>گیم<span class="brand-accent">‌زون</span><small>GAMEZONE STORE</small></span></a><div class="nav-actions"><?php if($u):?><a class="account" href="account.php">♙ <span><?=h($u['name'])?></span></a><?php if(admin()):?><a class="account" href="admin/">⚙ <span>مدیریت</span></a><?php endif;?><?php else:?><a class="account" href="account.php">♙ <span>ورود / ثبت‌نام</span></a><?php endif;?><a class="account" href="index.php">← <span>فروشگاه</span></a></div></div></header><main class="container"><?php if($m=flash()): ?><p class="notice"><?=h($m)?></p><?php endif; ?><?php } function page_end(): void { ?></main><script>document.addEventListener('click',e=>{const b=e.target.closest('[data-copy]');if(b){navigator.clipboard.writeText(b.dataset.copy);const t=b.textContent;b.textContent='کپی شد ✓';setTimeout(()=>b.textContent=t,1500);}const s=e.target.closest('[data-reveal]');if(s){s.closest('.code-box').classList.add('open');}});</script></body></html><?php } ?>
